
import numpy as np

DESCRIPTION = ("Mechanism: h0=0; h_t = relu(x_t*Wx + h_{t-1}@Wh), out = h8@Wo, decision = argmax class score. Written in the hidden-unit gauge that makes the input "
               "weights exactly +-1 (WXP below), so the 8 input weights cost no constants; the readout is applied in the difference (class-shift) basis, "
               "score_j - score_0, which also costs no constants. The recurrent matrix and the readout are generic trained weights, given exactly. "
               "The relus are active in almost every unit at every step, so the state propagates the 8 inputs multiplicatively through 7 recurrent steps "
               "(|h8| ~ 19, growing); class scores are near ties which makes the decision depend on every weight.")

P = np.maximum(np.array([-1, 1, -1, -1, -1, 1, 1, 1]), 0)     # relu of x1*Wx, positive part
N = np.maximum(-np.array([-1, 1, -1, -1, -1, 1, 1, 1]), 0)    # negative part
ABSWX = np.array([0.20729784667491913, 0.0301608107984066, 1.2026538848876953, 0.15057843923568726, 0.46720558404922485, 0.003241136437281966, 0.6188392639160156, 0.003973902203142643])

WH = np.array([0.08166094869375229, 2.6567275516146602, 0.127566450707482, -1.8324145724988203, -0.286746167927924, 9.158416073947011, -0.10815537135410978, 35.871949470377615, -0.020105822540730536, 0.47973573207855225, -0.02099602146086777, 0.018890782258171698, 0.049884440061303895, -11.162491239265197, -0.021876488048755492, 14.489686027779833, 3.8781806737034374, -6.193329173863094, 0.2350926101207733, 0.2866830477248705, 2.320427052669432, 650.840506581114, 1.8770882925004029, -157.30447928301118, 0.8914694730096675, 9.749853708087336, -0.07307151205117869, -0.6714730858802795, -0.062492372218554096, 45.06939857652002, 0.040863832358503674, 4.320688142678695, -0.7173341405463166, -13.394256035296438, -0.17506621963840704, 3.9676956443581974, 0.27209100127220154, -6.154472091578441, 0.405679022207119, -48.13023316122699, -0.003346786383584853, -0.00246404030187275, -0.0008569504583482117, 0.02362847193042648, -0.004602260425571391, 0.7854707837104797, 0.004537450532980237, 0.5006406119228205, 4.178934235314999, -2.3523344640512778, 0.26385916061018955, 1.355365640547343, 1.6005847381785439, 112.2699901224643, 0.4884464740753174, -171.84185217038882, -0.004719161816865754, 0.10419153346164983, 0.00011052814474536725, 0.002750683413346949, -0.0020842712636466886, 0.34613257230375155, 0.011661737987549778, -0.6003977656364441]).reshape(8, 8)

WO = np.array([-0.8520827889442444, -0.3523513376712799, -0.2431851625442505, -0.1793176680803299, -0.5581678152084351, -0.12887784838676453, 2.122230291366577, -0.37168437242507935, 0.6793951988220215, 0.11488478630781174, -0.05014205351471901, -0.22337594628334045, -1.25592839717865, -0.2163303792476654, 0.36263373494148254, 0.12629644572734833, -0.1604321300983429, 0.07165554910898209, -0.13588844239711761, 0.1546107828617096, 0.5336688756942749, 0.16727004945278168, 0.6589252352714539, -4.449883460998535, 0.42395371198654175, 0.023103484883904457, 0.1564648449420929, -0.1993415504693985, -0.2876906394958496, -2.5932154655456543, 1.3143192529678345, 0.04480009898543358, 0.5565202832221985, -0.0034317171666771173, 0.2121610790491104, 0.17322216928005219, 0.4811381995677948, 0.8646290898323059, -2.24717378616333, 0.26760333776474, 0.5339532494544983, 0.334181547164917, 0.5564365386962891, 0.27508848905563354, -0.1110694408416748, 0.24448417127132416, -2.479964256286621, 0.34418028593063354, -0.4326997995376587, -0.09884760528802872, -0.4477556645870209, 0.10506144165992737, 0.707349956035614, 0.10840223729610443, 0.027475543320178986, -0.09576715528964996, -0.0037737686652690172, 0.011276558972895145, 0.06721881777048111, -0.6583163142204285, 0.37224486470222473, 0.0292649082839489, -0.3640517592430115, 0.012961093336343765]).reshape(8, 8)

K = (WO[:, 1:] - WO[:, 0:1]) * ABSWX[:, None]     # gauge-basis readout, score_j - score_0

def model(x, iv):
    x = np.asarray(x)
    xp = iv("x1_pos", np.maximum(x[:, 0], 0.0))[:, None]
    xn = iv("x1_neg", np.maximum(-x[:, 0], 0.0))[:, None]
    h = xp * P + xn * N
    for t in range(2, 9):
        h = iv("h%d" % t, np.maximum(x[:, t - 1:t] * np.array([-1, 1, -1, -1, -1, 1, 1, 1]) + h @ WH, 0.0))
    return np.concatenate([np.zeros((h.shape[0], 1)), h @ K], axis=1)

ALIGN = {"x1_pos": ["h1"], "x1_neg": ["h1"]}
for t in range(2, 9):
    ALIGN["h%d" % t] = ["h%d" % t]
